#'
#' @export
dissocs <- function(
    case_a = 35,
    case_b = 48,
    controls_a = 50,
    controls_b = 50,
    sd_a = 10,
    sd_b = 10,
    alternative_a = "less",
    alternative_b = "less",
    sample_size = 20,
    correlation = 0.5,
    show_plot = FALSE,
    show_txt_output = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("dissocs requires jmvcore to be installed (restart may be required)")


    options <- dissocsOptions$new(
        case_a = case_a,
        case_b = case_b,
        controls_a = controls_a,
        controls_b = controls_b,
        sd_a = sd_a,
        sd_b = sd_b,
        alternative_a = alternative_a,
        alternative_b = alternative_b,
        sample_size = sample_size,
        correlation = correlation,
        show_plot = show_plot,
        show_txt_output = show_txt_output)

    analysis <- dissocsClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

